/*
- character: random
  $name: Character
  $options:
  - random: Random (surprise me)
  - cloud: Cloud 1
  - cloud2: Cloud 2
  - cloud3: Cloud 3
  - sephiroth: Sephiroth 1
  - sephiroth2: Sephiroth 2
  - tifa: Tifa
- pack: ff7
  $name: Character Pack
  $description: Which character pack Random picks from. A specific character is always shown, whatever you pick here.
  $options:
  - ff7: Final Fantasy VII
  - future: (more packs coming soon)
- corner: right
  $name: Corner
  $options:
  - right: Bottom right
  - left: Bottom left
- monitor: primary
  $name: Monitor
  $options:
  - primary: Primary monitor
  - cursor: The monitor with the mouse pointer
- sizePercent: 100
  $name: Size (%)
  $description: 100 is about 200 pixels tall at a normal DPI. Allowed range is 40 to 300.
- opacity: 100
  $name: Opacity (%)
  $description: Allowed range is 30 to 100.
- bubble: quote
  $name: Dialogue box
  $options:
  - quote: Time and a character quote
  - time: Time only
  - custom: My own message
  - none: No dialogue box
- timeFormat: 12h
  $name: Time format
  $description: Clock format shown in the dialogue box.
  $options:
  - 12h: 12-hour (AM/PM)
  - 24h: 24-hour
- customMessage: "It's {time}!"
  $name: My own message
  $description: "Used when the dialogue box is set to My own message. {time} is replaced with the current time."
- onTheHour: true
  $name: Show at the top of every hour
- intervalMinutes: 0
  $name: Also show every N minutes
  $description: Counted from midnight, so 15 means :00, :15, :30 and :45. Use 0 to turn this off. Allowed range is 0 to 720.
- customTimes: ""
  $name: Exact times
  $description: "Times of the day separated by commas, semicolons, spaces or the word \"and\". Examples: 9, 9am, 9 am, 9:30, 9.30pm, 9:30 a.m., 21:30, 12 am, noon, midnight. 24-hour input also works. Invalid entries are logged and shown in the preview bubble."
- quietFrom: 0
  $name: Quiet hours - from (hour, 0-23)
  $description: It does not show up between the two hours. Use the same value for both to turn quiet hours off. Example 23 and 8 means from 23:00 to 08:00.
- quietTo: 0
  $name: Quiet hours - to (hour, 0-23)
- stayTime: 6
  $name: Stay time (seconds)
  $description: How long the character stays after it has shown up. Allowed range is 2 to 60.
- clickToDismiss: true
  $name: Click to dismiss
  $description: Clicking the character makes it leave. When this is off, the character is click-through.
- skipFullscreen: false
  $name: Skip full-screen apps
  $description: Does not show up while a full-screen game, video or presentation is active. The preview ignores this.
- playSound: false
  $name: Play a sound
  $description: Plays the default Windows beep when the character shows up.
- previewOnSave: true
  $name: Preview when settings are saved
  $description: Shows the character once every time you save the settings, so you can see the result right away.
*/
// ==/WindhawkModSettings==

