// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

static inline float Clamp01(float v) {
    return v < 0.0f ? 0.0f : (v > 1.0f ? 1.0f : v);
}

static inline uint32_t Mul255(uint32_t a, uint32_t b) {
    return (a * b + 127) / 255;
}

static float EaseOutCubic(float t) {
    float u = 1.0f - Clamp01(t);
    return 1.0f - u * u * u;
}

static std::wstring GetStr(PCWSTR name) {
    std::wstring r;
    PCWSTR s = Wh_GetStringSetting(name);
    if (s) {
        r = s;
        Wh_FreeStringSetting(s);
    }
    return r;
}

static std::wstring ReplaceAll(std::wstring s, const std::wstring& from,
                               const std::wstring& to) {
    size_t pos = 0;
    while ((pos = s.find(from, pos)) != std::wstring::npos) {
        s.replace(pos, from.size(), to);
        pos += to.size();
    }
    return s;
}

// ---------------------------------------------------------------------------
// Base64
// ---------------------------------------------------------------------------

static int B64Value(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static std::vector<BYTE> Base64Decode(const char* text) {
    std::vector<BYTE> out;
    uint32_t acc = 0;
    int bits = 0;
    for (const char* p = text; *p; p++) {
        int v = B64Value(*p);
        if (v < 0) continue;  // whitespace and '=' are skipped
        acc = (acc << 6) | (uint32_t)v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out.push_back((BYTE)((acc >> bits) & 0xFF));
        }
    }
    return out;
}

